// Shape of src/data/gamedata.json (generated by scripts/wiki/build.mjs).

export type Dlc = "BaseGame" | "DLC1" | "DLC2" | "DLC3" | "DLC4" | "DLC5";

export interface Range {
  min: number;
  max: number;
}

export interface Location {
  name: string;
  dlc: Dlc;
  rareCustomers: string[];
}

export interface Ingredient {
  name: string;
  dlc: Dlc;
  category: string;
  level: number;
  price: number;
  tags: string[];
}

export interface Beverage {
  name: string;
  dlc: Dlc;
  level: number;
  price: number;
  alcohol: string | null;
  tags: string[];
}

export interface Recipe {
  name: string;
  dlc: Dlc;
  level: number;
  price: number;
  tags: string[];
  bannedTags: string[];
  ingredients: string[];
  cookware: string;
  cookTime: number;
}

export interface NormalCustomer {
  name: string;
  dlc: Dlc;
  locations: string[];
  likesAllTags: boolean;
  undocumented: boolean;
  likedFoodTags: string[];
  likedDrinkTags: string[];
  description: string;
}

export interface RareCustomer {
  name: string;
  shortName: string;
  kind: "rare" | "special";
  dlc: Dlc | null;
  homeLocation: string | null;
  budget: Range | null;
  locations: string[];
  undocumented: boolean;
  likedFoodTags: string[];
  dislikedFoodTags: string[];
  likedDrinkTags: string[];
}

export interface MerchantItem {
  name: string;
  type: string;
  probability: number;
  amount: Range | null;
}

export interface Merchant {
  name: string;
  dlc: Dlc;
  location: string | null;
  priceMultiplier: Range | null;
  items: MerchantItem[];
}

export interface Partner {
  name: string;
  shortName: string;
  dlc: Dlc;
  movementSpeed: string;
  workSpeed: string;
  revenueShare: number;
}

export interface GameData {
  meta: { source: string; fetchedAt: string; builtAt: string; dlcs: Dlc[] };
  locations: Location[];
  ingredients: Ingredient[];
  beverages: Beverage[];
  recipes: Recipe[];
  normalCustomers: NormalCustomer[];
  rareCustomers: RareCustomer[];
  merchants: Merchant[];
  partners: Partner[];
  tags: { food: string[]; drink: string[] };
}
